from collections import defaultdict
def f(g):
    H,W=len(g),len(g[0])
    cnt=defaultdict(int)
    for r in g:
        for x in r: cnt[x]+=1
    bg=max(cnt,key=cnt.get)
    res=[row[:] for row in g]
    for c in range(W):
        rs=[r for r in range(H) if g[r][c]!=bg]
        for aa,bb in zip(rs,rs[1:]):
            for r in range(aa+1,bb): res[r][c]=2
    for r in range(H):
        cs=[c for c in range(W) if g[r][c]!=bg]
        for aa,bb in zip(cs,cs[1:]):
            for c in range(aa+1,bb): res[r][c]=2
    return res
